import{_ as t,o,c as i,a3 as d}from"./chunks/framework.BlfGB29P.js";const p=JSON.parse('{"title":"Credit Notes Module","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Credit Notes Module | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/credit-notes-overview"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Credit Notes Module | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/credit-notes-overview"}]]},"headers":[],"relativePath":"user-guide/credit-notes-overview.md","filePath":"user-guide/credit-notes-overview.md","lastUpdated":1786227487000}'),a={name:"user-guide/credit-notes-overview.md"};function r(n,e,s,c,l,u){return o(),i("div",null,[...e[0]||(e[0]=[d('<h1 id="credit-notes-module" tabindex="-1">Credit Notes Module <a class="header-anchor" href="#credit-notes-module" aria-label="Permalink to &quot;Credit Notes Module&quot;">​</a></h1><p>Tenant customer-billing module on the frozen platform — the third Phase 3 (Billing) module, shipped alongside <a href="/user-guide/invoices-overview">Invoices</a> and <a href="/user-guide/payments-overview">Payments</a>. Issues credit notes against a tenant&#39;s own <a href="/user-guide/invoices-overview">Invoices</a> and, once applied, credits the invoice&#39;s <code>amount_credited</code> / <code>balance_due</code>.</p><p><strong>Hard dependency on Invoices.</strong> Like Payments, Credit Notes declares a <strong>required</strong> <code>module_dependencies</code> row on Invoices — a workspace must have Invoices installed before Credit Notes can be enabled from Marketplace.</p><blockquote><p><strong>Naming note:</strong> the backend model is <code>CustomerCreditNote</code> (table <code>customer_credit_notes</code>) — distinct from the platform&#39;s own <strong>Central</strong> platform-billing <code>credit_notes</code> ledger table (credits the platform issues <em>to</em> a tenant against its own module-subscription invoices). This module lets a tenant credit its <em>own customers</em>.</p></blockquote><h2 id="guides" tabindex="-1">Guides <a class="header-anchor" href="#guides" aria-label="Permalink to &quot;Guides&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Audience</th><th>Document</th></tr></thead><tbody><tr><td>Operators / workspace users</td><td><a href="/user-guide/credit-notes">credit-notes.md</a></td></tr><tr><td>Engineers</td><td><a href="/developer-guide/credit-notes">credit-notes.md</a></td></tr><tr><td>Production / ops</td><td><a href="/deployment/credit-notes">credit-notes.md</a></td></tr><tr><td>Module Development Standard</td><td><a href="/developer-guide/module-development">module-development.md</a></td></tr><tr><td>Reference blueprint</td><td><a href="/user-guide/payments-overview">payments-overview.md</a></td></tr><tr><td>Tenant API</td><td><a href="/api/tenant-v1-credit-notes">../api/tenant-v1-credit-notes.md</a></td></tr></tbody></table><h2 id="capabilities" tabindex="-1">Capabilities <a class="header-anchor" href="#capabilities" aria-label="Permalink to &quot;Capabilities&quot;">​</a></h2><ul><li>Credit note fields: title, required invoice link, optional contact/company link (defaults to the invoice&#39;s own contact/company), currency (defaults to the invoice&#39;s currency), issue date, notes</li><li>Auto-numbered (<code>CN-00001</code>; prefix backed by the <code>credit_notes_number_prefix</code> tenant setting, default <code>CN-</code> — not yet exposed in the Tenant Settings UI)</li><li>Line items (description, quantity, unit price, tax rate) — subtotal / tax total / total computed server-side, same pattern as Invoices</li><li>Status workflow: <code>draft → issued → applied</code>, with <code>void</code> available from <code>draft</code> or <code>issued</code> (<code>POST /credit-notes/{id}/issue</code>, <code>.../apply</code>, <code>.../void</code>) — <strong>applying</strong> a credit note adds its total to the invoice&#39;s <code>amount_credited</code> and recalculates <code>balance_due</code></li><li>Assignment with assignee scoping via <code>credit-notes.assign</code></li><li>Notes + domain activity timeline (mirrors Invoices/Payments)</li><li>Trash filtering plus <strong>Restore</strong> and <strong>Delete permanently</strong></li><li>Module licensing (<code>module:credit-notes</code>) + Spatie permissions — <strong>free Marketplace opt-in</strong> (Billing category), <strong>requires Invoices</strong></li><li>Audit + activity logging; assignment notification</li></ul><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><p><code>credit-notes.view</code> · <code>create</code> · <code>update</code> · <code>delete</code> · <code>restore</code> · <code>force.delete</code> · <code>assign</code> · <code>issue</code> · <code>apply</code> · <code>void</code></p><p>Enable Credit Notes from Marketplace (free) — <strong>Invoices must already be installed</strong>; Marketplace blocks the install otherwise. Catalog: slug <code>credit-notes</code>, category <code>billing</code>, <code>is_default_included = false</code>, <code>is_billable = false</code>, <code>sort_order = 30</code>.</p><h2 id="related-modules" tabindex="-1">Related modules <a class="header-anchor" href="#related-modules" aria-label="Permalink to &quot;Related modules&quot;">​</a></h2><p><strong>Required:</strong> <a href="/user-guide/invoices-overview">Invoices</a> — Credit Notes cannot be installed or created without it. <strong>Optional:</strong> Contacts and Companies (customer pickers only appear/validate when entitled). See <a href="/architecture/module-dependencies">Module Dependencies</a>.</p><h2 id="explicitly-deferred" tabindex="-1">Explicitly deferred <a class="header-anchor" href="#explicitly-deferred" aria-label="Permalink to &quot;Explicitly deferred&quot;">​</a></h2><ul><li>Refunding an already-applied credit note (once applied, a credit note is terminal — void is only available before applying)</li><li>Credit note PDF export / e-mail delivery to the customer</li><li>Standalone credit notes not tied to an invoice</li><li>Multi-currency conversion</li></ul>',15)])])}const g=t(a,[["render",r]]);export{p as __pageData,g as default};
